package com.sap.bfx.definition;import com.sap.bfx.utils.EnumUtils;import lombok.Data;import lombok.EqualsAndHashCode;import java.util.ArrayList;@EqualsAndHashCode(callSuper = true)@Datapublic class AttachmentElementDefinition extends ElementDefinition implements HasValueHelp {    private ValueHelpOption valueHelp;    private String fileTypes;    private AttachmentCardinality cardinality;    private AttachmentDesignType design = AttachmentDesignType.FileUploader;    private String adapter;    private boolean hasDescription;    private ArrayList<CategoryOptions> categories;    public AttachmentElementDefinition() {        super(UIElementType.Attachment);    }    public static AttachmentDesignType mapDesignType(String identifier) {        return EnumUtils.valueById(AttachmentDesignType.class, identifier, AttachmentDesignType.FileUploader);    }}